// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // Fuzzed parameter: an arbitrary address to use as `from`. We do not fuzz the callee address
    // because an EOA always makes the low-level call succeed; we only need to test the empty _tos case
    // which is independent of the callee behaviour.
    function testFuzz_property(address from) public {
        // Keep the domain wide but avoid the zero-address nonsense for `from` if desired.
        vm.assume(from != address(0));

        // Prepare empty arrays for _tos and v
        address[] memory tos = new address[](0);
        uint[] memory vals = new uint[](0);

        // Call transfer and catch whether it reverts.
        bool ok;
        try c.transfer(from, address(this), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: Reference contract requires _tos.length > 0 and therefore MUST revert (ok == false)
        // for every input where _tos is empty. The mutant that removed the require will return true (ok==true)
        // for some inputs, so this assertion will fail on that mutant for the empty-array case.
        assertTrue(!ok);
    }
}
